cssCode:
.snake-dot {
  position: absolute; width: 12px; height: 12px; background: #00ffcc;
  top: -6px; left: -6px; pointer-events: none; border-radius: 2px;
  box-shadow: 0 0 10px rgba(0,255,204,0.5);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;touch-action:none;';

const dots = [];
for(let i=0; i<12; i++){
  const d = document.createElement('div');
  d.className = 'snake-dot';
  c.appendChild(d);
  dots.push({el: d, x: -20, y: -20});
}

let mouse = {x: -20, y: -20};

c.addEventListener('pointermove', e => {
  const rect = c.getBoundingClientRect();
  mouse.x = e.clientX - rect.left; mouse.y = e.clientY - rect.top;
});

function anim() {
  let x = mouse.x, y = mouse.y;
  dots.forEach((dot, index) => {
    // ધીમેથી પાછળ આવવા માટેનું લોજિક (Lerp)
    dot.x += (x - dot.x) * 0.3;
    dot.y += (y - dot.y) * 0.3;
    dot.el.style.transform = `translate(${dot.x}px, ${dot.y}px) scale(${1 - index*0.06})`;
    x = dot.x; y = dot.y;
  });
  requestAnimationFrame(anim);
}
anim();
